head.script:
scwin.func = function(str, num, row) {
    return row % 2 == 0 ? "a" : "b";
}
scwin.__hasImgSort = function() {
    var b = true;
    WebSquare.wUnit.getJq("#gridView1_head_table th").each(function(i, el) {
        if (i == 1) {
            if (WebSquare.wUnit.getJq(el).find(".w2grid_head_sort_image_none").length === 0) {
                b = false;
            }
        } else if (WebSquare.wUnit.getJq(el).find(".w2grid_head_sort_image_none").length > 0) {
            b = false;
        }
    })
    return b;
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.__isSorted = function() {
    var arr = [];
    WebSquare.wUnit.getJq("#gridView1_body_tbody tr").not(".w2grid_hidedRow").find('td[col_id="column4"]').each(function(i, el) {
        arr.push(WebSquare.wUnit.getJq(el).text());
    })
    for (var i = 0; i < arr.length; i++) {
        if (arr[i] > arr[i + 1]) {
            return false;
        }
    }
    return true;
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 7. 브라우저에서 확인한다.
    //7. Check in the browser.
    // verify step 7. 상품명2컬럼을 제외하고 SorttableImage 가 보이게 된다.
    //7. SorttableImage is displayed except for the product name 2 column.
    WebSquare.wUnit.addCommand("assert", "scwin.__hasImgSort()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 8. 임의의 컬럼을 Sort 한다.
    //8. Sort any column.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_column2')");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 8. 임의의 컬럼이 Sort 된다.
    //8. Any columns are sorted.
    WebSquare.wUnit.addCommand("assert", "scwin.__isSorted()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
